const enforceAccent=true,screenshotTarget='login';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const settle=async()=>{document.getAnimations().forEach(a=>a.finish());await new Promise(resolve=>setTimeout(resolve,30));document.getAnimations().forEach(a=>a.finish());};
const ctx=document.createElement('canvas').getContext('2d');
const rgb=c=>{ctx.clearRect(0,0,1,1);ctx.fillStyle=c;ctx.fillRect(0,0,1,1);return Array.from(ctx.getImageData(0,0,1,1).data).slice(0,3)};
const lum=c=>rgb(c).map(x=>(x/=255)<=.04045?x/12.92:((x+.055)/1.055)**2.4).reduce((a,x,i)=>a+x*[.2126,.7152,.0722][i],0);
const ratio=(a,b)=>{const x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)};
const checks=[],samples=[],layouts=[];
const assert=(x,m)=>{if(!x)throw Error(m);checks.push(m)};
const initial=CalendarApp.exportSnapshot();
const box=n=>{const r=n.getBoundingClientRect();return [r.x,r.y,r.width,r.height]};
for(const id of ['checkout','login','export']){
 CalendarApp.openRequirement(id);await settle();
 const detail=$('#rf-detail'),panel=$('#rf-panel'),surface=getComputedStyle(detail).backgroundColor;
 const title=$('.rf-detail-title'),action=$('.rf-detail-actions .rf-primary'),color=getComputedStyle(action);
 const links=$$('.rf-section .rf-text-button:not(.rf-destructive)'),checkbox=$('.rf-task input'),destructive=$('.rf-destructive');
 samples.push({id,mode:'detail',action:color.backgroundColor,onAction:color.color,primaryContrast:ratio(color.color,color.backgroundColor),textActions:links.map(n=>getComputedStyle(n).color),checkbox:getComputedStyle(checkbox).accentColor,destructive:getComputedStyle(destructive).color,brandIcons:$$('.rf-resource-icon').map(n=>({kind:n.dataset.kind,color:getComputedStyle(n).color,background:getComputedStyle(n).backgroundColor})),globalAdd:getComputedStyle($('#rf-new')).backgroundColor});
 layouts.push({id,mode:'detail',panel:box(detail),title:box(title),sections:$$('.rf-section').map(box),footer:box($('.rf-detail-actions'))});
 assert(ratio(color.color,color.backgroundColor)>=4.5,id+' primary button readable');
 assert(links.every(n=>ratio(getComputedStyle(n).color,surface)>=4.5),id+' secondary actions readable');
 CalendarApp.editRequirement(id);await settle();
 const name=$('.rf-tab-panel[data-editor-panel=basic]>.rf-field input');name.focus();await settle();
 const selected=$('.rf-editor-tab[aria-selected=true]'),save=$('.rf-form-actions .rf-primary'),saveStyle=getComputedStyle(save),tabTone=getComputedStyle(selected,'::after').backgroundColor;
 const controls={id,mode:'edit',tabTone,nameFocus:getComputedStyle(name).borderBottomColor,checkbox:getComputedStyle($('.rf-task-edit input[type=checkbox]')).accentColor,save:saveStyle.backgroundColor,onSave:saveStyle.color,saveContrast:ratio(saveStyle.color,saveStyle.backgroundColor),textActions:$$('.rf-editor-section .rf-text-button').map(n=>getComputedStyle(n).color),primaryFocusOutline:getComputedStyle(save).outlineColor,globalAdd:getComputedStyle($('#rf-new')).backgroundColor};
 save.focus();await settle();controls.focusedSaveOutline=getComputedStyle(save).outlineColor;controls.focusVisible=save.matches(':focus-visible');
 name.focus();await settle();samples.push(controls);
 layouts.push({id,mode:'edit',panel:box($('#rf-detail')),name:box(name),fields:$$('.rf-field').map(box),sections:$$('.rf-editor-section').map(box),footer:box($('.rf-form-actions'))});
 assert(controls.saveContrast>=4.5,id+' save text readable');
 assert(!CalendarApp.hasUnsavedChanges(),id+' focusing controls leaves clean draft');
 assert(JSON.stringify(JSON.parse(CalendarApp.exportSnapshot()).requirements)===JSON.stringify(JSON.parse(initial).requirements),id+' stored requirements unchanged');
 if(enforceAccent){
  assert(rgb(controls.nameFocus).join()===rgb(tabTone).join(),id+' title focus matches tab tone');
  assert(rgb(controls.checkbox).join()===rgb(tabTone).join(),id+' checkbox matches requirement tone');
  assert(controls.textActions.every(c=>rgb(c).join()===rgb(tabTone).join()),id+' editing actions match requirement tone');
  if(controls.focusVisible)assert(rgb(controls.focusedSaveOutline).join()===rgb(tabTone).join(),id+' visible save outline matches requirement tone');
  if(id!=='checkout')assert(rgb(controls.save).join()===rgb(tabTone).join(),id+' save fill matches requirement tone');
 }
}
CalendarApp.editRequirement(screenshotTarget);await settle();
$('.rf-tab-panel[data-editor-panel=basic]>.rf-field input').focus();await settle();
return {checks,samples,layouts,storedSnapshot:initial,appearance:matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light',scope:'Actual isolated native WebKit computed colors, contrast, layout, persistence; synthetic focus/activation, transition endpoints only. Resolved outline does not prove trusted keyboard-visible branch.'};
